[
  {
    "id": "c001",
    "name": "1. Policy termination",
    "text": "Pursuant to Section XDI, entitled \"Cancellation/Nonrenewal/Conversion’”, this Policy shal] terminate at 12:01 a.m. (local time at the address shown in Item 1 of the Declarations) on 05/13/2009."
  },
  {
    "id": "c002",
    "name": "2. Discovery Period coverages",
    "text": "2. Subject to all provisions set forth in Section II], this Discovery Period Activation shall only apply to the coverages identified below: Discovery | Discovery ; is ; . Period Period Insuring Agreement oo Retention Premium Effective [Expiration ety Date Date Directors and Officers Liability $10,000,000 $160,000 $11,381 05/13/2009 | 05/13/2010 Broad Form Company Liability $5,000,000 $100,000 $8,536 05/13/2009 | 05/13/2010 Securities Liability 310,000,000 $100,000 $5,121 05/13/2009 | 05/13/2010 Fiduciary Liability $5,060,000 $5,000 $1,087 05/13/2009 | 05/13/2010 Brokerage/Advisory Services Liability $5,000,000 | $100,000 $1,830 05/13/2009 | 05/13/2010"
  },
  {
    "id": "c003",
    "name": "3. Acquisition retention",
    "text": "If the Discovery Period is purchased as a result of the Company being acquired or merged with another entity and the acquiring entity is legally permitted to indemnify the Insured Persons, regardless of whether actual indemnification is granted, the retention applicable to Insuring Agreement (B) shall apply to such Loss, unless by reason of its Financial Impairment the acquiring entity does not make indemnification."
  },
  {
    "id": "c004",
    "name": "4.E. Company definition",
    "text": "E. Company, means the entity or entities set forth in Item 1 of the Declarations, any Subsidiary created or acquired as of the inception date set forth in Item 2 of the Declarations, and, the acquinng entity, but only for Wrongful Acts involving the entity or entities set forth in Item 1 of the Declarations and only for Wrongful Acts occurring prior to the termination date of this Policy."
  },
  {
    "id": "c005",
    "name": "Discovery Period noncancellability",
    "text": "The Discovery Period is noncancellable and the entire premium for this Endorsement shal! be deemed to be fully earned at its commencement."
  },
  {
    "id": "c006",
    "name": "Endorsement effective date",
    "text": "This Endorsement shall be effective as of 12:01 a.m. on 05/13/2009."
  },
  {
    "id": "c007",
    "name": "Preservation of policy terms",
    "text": "Nothing herein contained shall be held to vary, alter, waive or extend any of the terms, conditions, provisions, agreements or limitations of the Policy other than as above stated."
  },
  {
    "id": "c008",
    "name": "Important notice",
    "text": "IMPORTANT NOTICE: This is a claims-made policy written on a no duty to defend basis. Defense Costs are included within the Limit of Liability. Amounts incurred as Defense Costs will reduce the Limit of Liability available to pay judgments or settlements. Please read this Policy carefully."
  },
  {
    "id": "c009",
    "name": "Item 1. Named Insured(s)",
    "text": "Ment 1. Named Insured(s): vant ederal Sa ares, Inc. First Federal Bank First Financial Corporation of Sioux City Sioux Financial Company United Escrow, Inc. Equity Services, Inc. Sioux Abstract Company Rerick Abstract Company Principal Office: 329 Pierce Street Sioux City, [A 51101"
  },
  {
    "id": "c010",
    "name": "Item 2. Policy Period",
    "text": "Item 2. Policy Period: From 12:01 a.m. 04/13/2006 To 12:01 a.m. 0443/2009 (Local time at the address shown in Item"
  },
  {
    "id": "c011",
    "name": "Item 3. Total Policy Limit",
    "text": "Item 3. Total Policy Limit: The Total Policy Limit for each Policy Year during the Policy Period for all Insuring Agreements, regardless of whether such Insuring Agreement is paovises as a sublimit or separate limit, shall not exceed $10,000,000."
  },
  {
    "id": "c012",
    "name": "Item 4. Discovery Period",
    "text": "Item 4. Discovery Period: If the eligibility requirements are met and the Discovery Period is properly exercised, the Insured shall pay 75% of the annual premium set forth in Item 10 (a). The length of the Discovery Period shall be 365 days."
  },
  {
    "id": "c013",
    "name": "Item 5. Notices",
    "text": "Item 5. Notices: Al) notices required to be given to the Insurer under this Policy shall be addressed to Progressive Casualty Insurance Company,. Professional Liability Group, 5920 Landerbrook Drive, PLG-L21, Mayfield Heights, Ohio 44124. Telephone: 800-274-5222."
  },
  {
    "id": "c014",
    "name": "Item 6. Coverage(s) Provided",
    "text": "Item 6. Coverage(s) Provided: It is understood and agreed that coverage will not be provided under any Insuring Agreement unless a Limit of Liability, retention and premium for such Insuring Agreement are set forth below:"
  },
  {
    "id": "c015",
    "name": "Broad Form Company Liability coverage",
    "text": "The Broad Form Company Liability Insuring Agreement includes coverage for Broad Form Lender Liability, Depositor Liability, Securities Liability, and HRA/Keogh Liability coverage. If a different Limit of Liability or retention is desired for any of these coverages, coverage will be excluded under Insuring Agreement (C) and a separate Insuring Agreement will be provided."
  },
  {
    "id": "c016",
    "name": "Item 11. IRA/Keogh Liability Retention",
    "text": "Item 11. IRA/Keogh Liability Retention: The retention for IRA/Keogh Claims pursuant to Section ITV (X)(2) or the Broad Form Company Liability Insuring Agreement (if applicable), shall be $5,000. If IRA/Keogh coverage is provided by Endorsement, coverage shall be subject to the retention set forth in Item 9 above."
  },
  {
    "id": "c017",
    "name": "Item 13. Endorsements",
    "text": "Item 13. Endorsements: This Policy is subject to the terms of the following Endorsements attached hereto and incorporated herein by reference at the effective date of this Policy and to ail other Endorsements attached hereto after the effective date of this Policy: 2949, 5091, 5093, 5098, 2223, TRIA-01, 8790D (IA), 500! | 5 0€ > aH"
  },
  {
    "id": "c018",
    "name": "Contract documents",
    "text": "These Declarations, along with the completed and signed Application, including attachments, the Policy and all Endorsements hereto, shal] constitute the contract between the Insured Persons, the Company and Progressive Casualty Insurance Company, 6300 Wilson Mills Road, Mayfield Village, Ohio 44143."
  },
  {
    "id": "c019",
    "name": "Item 2. New Policy Period",
    "text": "Item 2. Previous Policy Period: FROM: 12:01 a.m. 04/13/2006 TO: 12:01 a.m. 04/13/2009 New Policy Period: FROM: 12:01 a.m. 04/13/2006 TO: 12:01 a.m. 05/13/2009 (Locai time at the address shown in Item 1.)"
  },
  {
    "id": "c020",
    "name": "Item 13. Endorsements",
    "text": "Item 13. Endorsements: This Policy is subject to the terms of the following Endorsements attached hereto and incorporated herein by reference at the effective date of this Policy and to all other Endorsements attached hereto after the effective date of this Policy: 5081, 5082, 2223, 2949, 5091, 5093, 5098, TRIA-01, 8790D (IA)"
  },
  {
    "id": "c021",
    "name": "Endorsement effective date",
    "text": "This Endorsement shall be effective as of 12:01 a.m. on 04/13/2009."
  },
  {
    "id": "c022",
    "name": "Preservation of policy terms",
    "text": "Nothing herein contained shall be held to vary, alter, waive or extend any of the terms, conditions, provisions, agreements or limitations of the Policy other than as above stated."
  },
  {
    "id": "c023",
    "name": "Item 1. Changed Named Insured(s)",
    "text": "Item 1. Named Insured(s): FROM: First Federal Bankshares, Inc. First Federal Bank First Financial Corporation of Sioux City Sioux Financial Company United Escrow, Inc. Equity Services, Inc. Sioux Abstract Company Rerick Abstract Company TO: Vantus Bank Fisst Federal Bankshares, Inc. First Federal Bank First Financial Corporation of Sioux City Sioux Financial Company United Escrow, Inc. Equity Services, Inc. Sioux Abstract Company Rerick Abstract Company"
  },
  {
    "id": "c024",
    "name": "Item 13. Endorsements",
    "text": "Item 13. Endorsements: This Policy is subject to the terms of the following Endorsements attached hereto and incorporated herein by reference at the effective date of this Policy and to all other Endorsements attached hereto after the effective date of this Policy: 5081, 2223, 2949, 5091, 5093, 5098, TRIA-01, 8790D (IA)"
  },
  {
    "id": "c025",
    "name": "Endorsement effective date",
    "text": "This Endorsement shall be effective as of 12:01 a.m. on 09/04/2007."
  },
  {
    "id": "c026",
    "name": "Preservation of policy terms",
    "text": "Nothing herein contained shall be held to vary, alter, waive or extend any of the terms, conditions, provisions, agreements or limitations of the Policy other than as above stated."
  },
  {
    "id": "c027",
    "name": "Important notice",
    "text": "IMPORTANT NOTICE: This is a claims-made policy written on a no duty to defend basis. Defense Costs are included within the Limit of Liability. Amounts incurred as Defense Costs will reduce the Limit of Liability available to pay judgments or settlements. Please read this Policy carefully."
  },
  {
    "id": "c028",
    "name": "General coverage agreement",
    "text": "In consideration of the premium paid and in reliance upon all statements made and information contained in the Declarations and Application, the Insurer and the Insured agree that coverage will be provided subject to all of the terms, conditions and limitations of this Policy, as follows:"
  },
  {
    "id": "c029",
    "name": "Section I coverage prerequisite",
    "text": "SECTION J - INSURING AGREEMENTS It is understood and agreed that coverage will not be provided under any Insuring Agreement unless a Limit of Liability, retention and premium for such Insuring Agreement are set forth in the Declarations."
  },
  {
    "id": "c030",
    "name": "A. Insured Persons Liability Coverage",
    "text": "A. INSURED PERSONS LIABILITY COVERAGE The Insurer will pay on behalf of the Insured Persons, Loss resulting from Claims first made during the Policy Period or the Discovery Period against the Insured Persons for which the Insured Persons are legally obligated to pay for Wrongful Acts, except for Loss the Company pays as indemnification."
  },
  {
    "id": "c031",
    "name": "B. Company Indemnification Coverage",
    "text": "B. COMPANY INDEMNIFICATION COVERAGE The Insurer will pay on behalf of the Company, Loss resulting from Claims first made during the Policy Period or the Discovery Period against the Insured Persons for which the Company has agreed to or is legally permitted or required by law to indemnify the Insured Persons for Wrongful Acts."
  },
  {
    "id": "c032",
    "name": "C. Broad Form Company Liability Coverage",
    "text": "es BROAD FORM COMPANY LIABILITY COVERAGE The Insurer will pay on behalf of the Company, Loss resulting from Claims first made during the Policy Period or the Discovery Period against the Company for which the Company is legally obligated to pay for Wrongful Acts."
  },
  {
    "id": "c033",
    "name": "Section II.A. Estates, Heirs and Marital Estate Liability",
    "text": "SECTION H - ADDITIONAL COVERAGES A. ESTATES HEIRS AND MARITAL ESTATE LIABILITY This Policy shal] cover Loss resulting from Claims for Wrongful Acts of an Insured Person made against: Form No. 5089 (01/05) FDIC No, 27732 Case 5:12-cv-04041-MWB-LTS Document 2-1 Filed 04/25/12 Page 8 of 4d\" > a) the estates, heirs, Jegal representatives or assigns of any Insured Persons who are deceased, incompetent, insolvent or bankrupt; provided that such Claims would have been covered by this Policy in the absence of such death, incompetency, insolvency or bankruptcy; and (2) __ the lawful spouse of an Insured Person solely by reason of such person's status as a spouse or - such spouse's ownership interest in property which the claimant seeks as recovery for an alleged Wrongful Act of such Insured Person. The coverage provided by this Subsection shall not apply with respect to any loss arising from any act or omission by an Insured Person's estate, heirs, legal representatives, assigns, or spouse."
  },
  {
    "id": "c034",
    "name": "Section II.B. Not-for-Profit Directorships",
    "text": "NOT-FOR-PROFIT DIRECTORSHIPS This Policy shall cover Loss resulting from Claims for Wrongful Acts committed by Insured Persons while serving on the board of directors, board of trustees, or as officers of any not-for-profit entity at the direction of the Company; provided, however, that this coverage shall be excess over any other insurance or indemnification available to the Insured Persons."
  },
  {
    "id": "c035",
    "name": "Section III. Right to purchase Discovery Period",
    "text": "SECTION Li - DISCOVERY PERIOD If the Company or the Insurer cancels or nonrenews this Policy or any Insuring Agreement, or if the Policy converts subject to Section XIII (C)(1)(b), the Insured shall have the right to purchase an optional extended reporting period (herein called the Discovery Period) for the period set forth in Item 4 of the Declarations. It is understood that if the Insurer cancels this Policy duc to nonpayment of premium, the Insured shall not be entitled to the Discovery Period."
  },
  {
    "id": "c036",
    "name": "Section III. Discovery Period scope",
    "text": "The Discovery Period is noi an extension of coverage, but rather an extended reporting period for Claims first made during the Discovery Period resulting from Wrongful Acts that occurred prior to the effective date of cancellation, nonrenewal or conversion and otherwise covered under this Policy. Notice of facts and circumstances that may give rise to a Claim, pursuant to Section X (B), must be given during the Policy Period and shall not be effective if given during the Discovery Period."
  },
  {
    "id": "c037",
    "name": "Section III. Discovery Period premium",
    "text": "If the Insured elects to purchase the Discovery Period, the premium will be calculated by multiplying the annual premium set forth in Item 10 (a) of the Declarations by the percentage set forth in Item 4 of the Declarations. The Discovery Period is noncancellable and the entire premium shall be deemed fully eamed at its commencement."
  },
  {
    "id": "c038",
    "name": "Section III. Election deadline",
    "text": "The Insureds’ right to purchase the Discovery Period shall lapse unless the Insurer receives written notice of the Insureds’ election and full payment of the additional premium due within sixty (60) days after the effective date of such cancellation, nonrenewal or conversion."
  },
  {
    "id": "c039",
    "name": "Section III. Discovery Period limit",
    "text": "The Limit of Liability with respect to Claims made during the Discovery Period shall be part of and not in addition to the Limit of Liability set forth in Item 8 of the Declarations, for each respective Insuring Agreement, for all Claims made during the immediately preceding Policy Year. Any Claim made during the Discovery Period shall be deemed to be made during the Policy Year immediately preceding the Discovery Period."
  },
  {
    "id": "c040",
    "name": "Section III. Renewal offer",
    "text": "The offer by the Insurer @ acceptance by the Insured of continued coverage under terms, conditions, Limits of Liability, retentions, or premiums different from those applicable to the expiring Policy shall not constitute a refusal to renew and shall not entitle any Insured to exercise the Discovery Period."
  },
  {
    "id": "c041",
    "name": "Section IV.A. Application",
    "text": "a SECTION IV - DEFINITIONS Application means all applications, attachments and materials submitted to the Insurer for this Policy or any Policy of which this Policy is a direct or indirect renewal or replacement. All such applications, attachments and materials are deemed attached to and incorporated into this Policy, as if physically attached."
  },
  {
    "id": "c042",
    "name": "Section IV.B. Brokerage/Advisory Services",
    "text": "Brokerage/Advisory Services means the purchase or sale of securities, mutual funds, annuities, variable annuities, life, accident or health insurance which have been approved by the Company to be transacted through a Registered Representative of the Company or a third party service provider pursuant to a contract between the Company and the service provider. In connection with the foregoing activities, Brokerage/Advisory Services also includes the provision of: (1) economic advice, financia] advice or investment advisory services; and (2) financial planning advice including without limitation any of the following activities in conjunction therewith: the preparation of financial plans or personal financial statements, and the giving of advice with regard to insurance, savings, investments, retirement planning or taxes. Brokerage/Advisory Services shall not include rendering advice with regard to the FDIC-insured component of any deposit account or the sale of credit life or disability insurance incidental to the issuance of a loan."
  },
  {
    "id": "c043",
    "name": "Section IV.C. Claim",
    "text": "Claim, either in singular or plural, means any of the following instituted against an Insured Person or against the Company, but only to the extent coverage is granted to the Company: (1) a written or oral demand for monetary damages or non-monetary relief, (2) a civil proceeding commenced by the service of a complaint or similar pleading; (3) — acriminal proceeding commenced by a return of an indictment; (4) an arbitration or mediation proceeding in which monetary damages are sought; (5) a formal administrative or regulatory proceeding commenced by the filing of a notice of charges, formal investigative order or similar document; or (6) a written request to toll or waive a statute of limitations, relating to a potential Claim described in Items (1) through (5) above, for a Wrongfui Act including any appeal from such proceeding."
  },
  {
    "id": "c044",
    "name": "Section IV.D. COBRA",
    "text": "COBRA means the Consolidated Omnibus Budget Reconciliation Act, as amended."
  },
  {
    "id": "c045",
    "name": "Section IV.E. Company",
    "text": "Company means the entity or entities set forth in Item 1 of the Declarations, any Subsidiary created or acquired as of the inception date set forth in Item 2 of the Declarations, and, subject to Section XII (B), any bank Subsidiary created or acquired during the Policy Period. 3"
  },
  {
    "id": "c046",
    "name": "Section IV.F. Defense Costs",
    "text": "Fs Defense Costs means reasonable and necessary legal fees and expenses incurred in defending or investigating any Claim and the cost of appeal, attachment or similar bonds. Defense Costs shall not include salaries, wages, overhead, or benefit expenses incurred by the Insured."
  },
  {
    "id": "c047",
    "name": "Section IV.G. ERISA",
    "text": "G. ERISA means the Employment Retirement Income Security Act of 1974, as amended."
  },
  {
    "id": "c048",
    "name": "Section IV.H. Employee",
    "text": "H. Employee, either in singular or plural, means any natural person, other than a Leased Employee or Independent Contractor, who is a past, present or future employee of the Company including any parttime, seasonal or temporary employee, acting in their capacity as such."
  },
  {
    "id": "c049",
    "name": "Section IV.I. Financial Impairment",
    "text": "I. Financial Impairment means the status of the Company resulting from: (1) the appointment by any state or federal official, regulatory agency or court of any receiver, conservator, liquidator, trustee, rehabilitator or similar official to take control of, supervise, manage, or liquidate the Company or any Subsidiary; or (2) the Company or any Subsidiary becoming a debtor in possession."
  },
  {
    "id": "c050",
    "name": "Section IV.J. Insured",
    "text": "J. Tasured, either in singular or plural, means the Insured Persons and the Company."
  },
  {
    "id": "c051",
    "name": "Section IV.K. Insured Person",
    "text": "K Insured Person, cither in singular or plural, means any past, present or future director, member of the board of trustees, officer, Employee, honorary or advisory director, or honorary or advisory member of the board of trustees of the Company."
  },
  {
    "id": "c052",
    "name": "Section IV.L. Insurance Services",
    "text": "7 Insurance Services means any of the following services performed by an Insured as insurance agent, insurance broker, insurance consultant or insurance managing general agent: (1) sale and placement of insurance; (2) identification, analysis and evaluation of a client's insurance needs, including work performed for prospective clients; (3) appraisal of property and inspections for insurance purposes; (4) —_ adjustment of claims on behalf of insurance companies, including Joss payments; or (5) arrangement of premium financing for clients."
  },
  {
    "id": "c053",
    "name": "Section IV.M. Interrelated Wrongful Acts",
    "text": "M. _Interrelated_ Wrongful Acts means Wrongful Acts which have as a common nexus any fact, circumstance, situation, event, transaction or series of related facts, circumstances, situations, events or transactions."
  },
  {
    "id": "c054",
    "name": "Section IV.N. Loss",
    "text": "N. Loss means Defense Costs and any amount which the Insured Persons or the Company (if applicable) are Jegally obligated to pay resulting from a Claim, including damages, judgments, settlements, pre- and post-judgment interest, punitive or exemplary damages and the multiple portion of any multiplied damage award where insurable by law. Loss shall not include: (1) taxes; (2) criminal or civil fines or penalties imposed by law: Form No. 5089 (01/05) FDIC No. 27732 Case 5:12-cv-04041-MWB-LTS Document 2-1 Filed 04/25/12 Page 11 of 40PR° 7S (3) any unpaid, unrecoverable or outstanding loan, lease or extension of credit to any customer or any forgiveness of debt; (4) costs to comply with any non-monetary or injunctive relief of any kind or any agreement to provide such relief, including but not limited to any damages, costs or expenses incurred in making an accommodation for any disabled person pursuant to the Americans with Disabilities Act or any similar federal, state or local laws, or in complying with any other federal, state or local Jaws of any kind; (5) other than Defense Costs, that portion of Loss that the Company is obligated to pay pursuant to any express written or oral contract or agreement existing prior to the date the Claim is made; provided, however, if it is established in fact that such Claim involves an intentional breach of contract, the Insured agrees to reimburse the Insurer for such Defense Costs; - (6) the depreciation (or failure to appreciate) in value of any investment product, including securities, commodities, currencies, options or futures due to market fluctuation unrelated to any Wrongful Act; (7) any restitution, disgorgement, or payment of similar sums including but not limited to the retum of fees, commissions or charges for the Company's services; or (8) any matters which are uninsurable under the law pursuant to which this Policy shall be construed."
  },
  {
    "id": "c055",
    "name": "Section IV.O. Loss Information",
    "text": "Loss Information means information on open, closed and potential Claims, including date, description, and payment amounts, if any."
  },
  {
    "id": "c056",
    "name": "Section IV.P. Named Insured",
    "text": "Named Insured means the first named entity set forth of Item 1 of the Declarations."
  },
  {
    "id": "c057",
    "name": "Section IV.Q. Policy",
    "text": "Policy means collectively, the Declarations, the Application, this policy form and any Endorsements attached hereto."
  },
  {
    "id": "c058",
    "name": "Section IV.R. Policy Period",
    "text": "Policy Period means the period from the inception date set forth in Item 2 of the Declarations to the expiration date set forth in Item 2 of the Declarations or any earlier termination date."
  },
  {
    "id": "c059",
    "name": "Section IV.S. Policy Year",
    "text": "Policy Year means the period of one year following the effective date and hour of this Policy or any anniversary thereof, or if the time between the effective date and termination of the Policy Period is less than one year, such lesser period. Any extension of the Policy Period shall not result in an increase or reinstatement of the Limit of Liability. ]f the Policy Period is extended beyond its original expiration date, the period of the extension shall be a part of the Policy Year, which would have ended on the original expiration date."
  },
  {
    "id": "c060",
    "name": "Section IV.T. Pollutants",
    "text": "Pollutants include but are not limited to any solid, liquid, gaseous or thermal organism, nritant or contaminant, including smoke, vapor, soot, fumes, acids, alkalis, chemicals, hazardous substances, nuclear materials and waste. Waste includes materials to be recycled, reconditioned or reclaimed."
  },
  {
    "id": "c061",
    "name": "Section IV.U. Registered Representative",
    "text": "Registered Representative means an individual who is: (1) registered with the National Association of Secunties Dealers; or (2) a life insurance agent or insurance broker who is licensed by the appropriate regulatory authonties."
  },
  {
    "id": "c062",
    "name": "Section IV.V. Subsidiary",
    "text": "(1) any entity in which the Company owns, directly or through one or more subsidiaries, more than fifty percent (50%) of the outstanding securities representing the present right to vote for the election of directors; vy, Subsidiary means: (2) any limited liability company in which the Company, or one or more of its subsidianes, has the right to appoint or designate fifty percent (50%) or more of such limited lability company's managers; or (3) any joint venture in which the Company, or one or more of its subsidiaries, has the right to elect, appoint or designate more than fifty percent (50%) of such entity's directors, trustees or other equivalent executives."
  },
  {
    "id": "c063",
    "name": "Section IV.W. Trust Department Services",
    "text": "W. Trust Department Services means any of the following services performed by an Insured through a Trust Department or Trust Subsidiary of the Company: (1) administrator, custodian or trustee under any individual retirement account (IRA) or H.R. 10 Plan (Keogh Plan); (2) executor, administrator, or personal representative of estates, administrator of guardianships, trustee under personal or corporate trust agreements, or conservator of any person; (3) trustee under a pension, profit sharing, health and welfare or any other employee benefit plan or trust, other than an employee benefit plan or trust sponsored or established by the Company for its own Employees; (4) custodian, depository or managing agent for securities or real property, manager of any personal property owned by others, attorney-in-fact, interest or dividend disbursing agent, transfer or paying agent, redemption or subscriptions agent, fiscal agent, tax withholding agent, registrar of securities, agent for voting securities, sinking fund agent, escrow agent or trustee under a corporate bond indenture; or (5) __ trustee exercising any other trust or fiduciary powers permitted by Jaw."
  },
  {
    "id": "c064",
    "name": "Section IV.X. Wrongful Act",
    "text": "Xx. Wrongful Act, either in singular or plural, means any actual or alleged act, error, omission, misstatement, misleading statement, neglect or breach of duty by: QQ) any Insured Person in the discharge of their duties while acting solely in the capacity as such or while acting solely in the capacity as director, officer, or member of the board of trustees of a notfor-profit entity pursuant to Section II (B); (2) any Insured Person in the discharge of their duties while acting solely in the capacity as administrator, custodian or trustee under any individual retirement account (IRA) or H.R. 10 Plan (Keogh Plan) outside of the scope of any Trust Department or Trust Subsidiary of the Company; or (3) the Company or any person or entity for which the Company is legally responsible, but only to the extent that coverage is granted to the Company by Insuring Agreement made a part of this Policy."
  },
  {
    "id": "c065",
    "name": "Section V. Applicability",
    "text": "SECTION V - EXCLUSIONS APPLICABLE TO ALL INSURING AGREEMENTS Form No. 5089 (01/05) FDIC No. 27732 Case 5:12-cv-04041-MWB-LTS Document 2-1 Filed 04/25/12 Page 13 of 4@RG 0078 The following Exclusions are applicable to all Imsureds under all Insuring Agreements made a part of this Policy."
  },
  {
    "id": "c066",
    "name": "Section V.A. Bodily/Personal Injury and Property Damage Exclusion",
    "text": "A. Bodily/Personal Injury and Property Damage Exclusion - The Insurer shall not be liable to make any payment for Loss in-connection with any Claim for actual or alleged bodily injury, sickness, disease, or death of any person, damage to or destruction of any tangible or intangible property including loss of use thereof, wrongful entry, eviction, false arrest, false imprisonment, malicious prosecution, abuse of process, assault, battery, mental anguish, emotional distress, loss of consortium, invasion of privacy, defamation, false light, libel, or slander."
  },
  {
    "id": "c067",
    "name": "Section V.B. Brokerage/Advisory Services Exclusion",
    "text": "B. Brokerage/Advisory Services Exclusion - The Insurer shall not be liable to make any payment for Loss in connection with any Claim arising out of or in any way involving the rendering or failing to render Brokérage/Advisory Services."
  },
  {
    "id": "c068",
    "name": "Section V.C. Collusion Exclusion",
    "text": "Cc. Collusion Exclusion - The Insurer shall not be Hable to make any payment for Loss in connection with any Claim by any security holder of the Company, whether directly or derivatively, unless such security holder bringing such Claim is acting independently of, and totally without the solicitation, assistance, participation, or intervention of any Insured or any affiliate of the Company."
  },
  {
    "id": "c069",
